{
  "decision-bounded-remainder-barcode": "WITH RECURSIVE candidates(barcode_id, value, high_value) AS (SELECT barcode_id, max(low_value, 0), high_value FROM barcodes WHERE max(low_value, 0) <= high_value UNION ALL SELECT barcode_id, value + 1, high_value FROM candidates WHERE value < high_value) SELECT c.barcode_id, min(c.value) AS missing_value FROM candidates AS c WHERE NOT EXISTS (SELECT 1 FROM remainder_checks AS r WHERE r.barcode_id = c.barcode_id AND c.value % r.modulus <> r.required_remainder) GROUP BY c.barcode_id ORDER BY c.barcode_id ASC",
  "decision-bridge-disjoint-route-pair": "SELECT a.route_id AS route_a, b.route_id AS route_b, a.duration_min + b.duration_min AS total_min FROM routes AS a JOIN routes AS b ON a.route_id COLLATE BINARY < b.route_id WHERE NOT EXISTS (SELECT 1 FROM crossings AS x JOIN crossings AS y ON x.bridge_id = y.bridge_id WHERE x.route_id = a.route_id AND y.route_id = b.route_id) ORDER BY total_min ASC, route_a COLLATE BINARY ASC, route_b COLLATE BINARY ASC LIMIT 1",
  "decision-bridge-print-spool-roll-ranges": "WITH overlaps AS (SELECT a.run_id AS a_run, b.run_id AS b_run, max(a.first_roll, b.first_roll) AS first_shared_roll, min(a.last_roll, b.last_roll) AS last_shared_roll FROM spool_a AS a JOIN spool_b AS b ON a.first_roll <= b.last_roll AND b.first_roll <= a.last_roll) SELECT a_run, b_run, first_shared_roll, last_shared_roll, last_shared_roll - first_shared_roll + 1 AS shared_roll_count FROM overlaps ORDER BY a_run COLLATE BINARY ASC, b_run COLLATE BINARY ASC",
  "decision-budget-one-shift-of-retention-calls": "WITH choices(portfolio, spend_cents, net_cents) AS (SELECT '', 0, 0 UNION ALL SELECT batch_code, outlay_cents, forecast_cents - outlay_cents FROM call_batches UNION ALL SELECT a.batch_code || ',' || b.batch_code, a.outlay_cents + b.outlay_cents, (a.forecast_cents - a.outlay_cents) + (b.forecast_cents - b.outlay_cents) FROM call_batches AS a JOIN call_batches AS b ON a.batch_code COLLATE BINARY < b.batch_code AND a.desk_code <> b.desk_code) SELECT portfolio, spend_cents, net_cents FROM choices WHERE spend_cents <= 100 ORDER BY net_cents DESC, spend_cents ASC, portfolio COLLATE BINARY ASC LIMIT 1"
}
